public delegate void MessageHandler(string receiptHandle, ReadOnlyMemory<byte> body);

public sealed class RabbitOffload
{
    public MessageHandler? OnMessage { get; set; }

    public void Dispatch(string handle, ReadOnlyMemory<byte> body)
        => OnMessage?.Invoke(handle, body);
}

Func<string, ReadOnlyMemory<byte>, bool> shouldAck =
    static (handle, body) => body.Length > 0;

