public event Action<string>? Processed;

public void RaiseProcessed(string messageId)
{
    var handlers = Processed;
    if (handlers is null) return;

    foreach (var d in handlers.GetInvocationList())
    {
        try { ((Action<string>)d)(messageId); }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"handler failed for {messageId}: {ex.Message}");
        }
    }
}

public void RaiseWithTelemetry(string messageId)
{
    var handlers = Processed;
    if (handlers is null) return;

    var list = handlers.GetInvocationList();
    _metrics.RecordHandlerCount(list.Length);

    foreach (var d in list)
    {
        try { ((Action<string>)d)(messageId); }
        catch (Exception ex)
        {
            _metrics.RecordHandlerFailure(d.Method.Name);
            _logger.LogError(ex, "handler {Handler} failed for {Id}", d.Method.Name, messageId);
        }
    }
}
